return new{scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,dirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty,playing=UnityEditor.EditorApplication.isPlaying,background=Application.runInBackground,waves=UnityEngine.Object.FindObjectsOfType<WaveManager>().Select(w=>new{w.name,waves=w.waves.Select(r=>new{prefab=UnityEditor.AssetDatabase.GetAssetPath(r.enemyPrefab),r.enemyCount,r.spawnInterval}).ToArray()}).ToArray()};
